(function () {
    "use strict";
    // Simple tags input component without dependencies; Bootstrap-friendly chips.
    // Allowed chars: letters, numbers, - _ . / and internal spaces. ASCII only.
    var TAG_RE = /^[A-Za-z0-9._\-\/ ]+$/;
    var MAX_TAGS = 20, MAX_LEN = 32, MAX_TOTAL = 512;
    function el(tag, cls) { var e = document.createElement(tag); if (cls) e.className = cls; return e; }
    function toCSV(arr) { return arr.join(","); }
    function normalizeCSV(csv) { if (!csv) return []; return csv.split(',').map(function (s) { return s.trim(); }).filter(function (s) { return s.length > 0; }); }
    function TagsState(container) { this.c = container; this.input = container.querySelector('input[type="text"]'); this.invalid = document.getElementById('tagInvalid'); this.hidden = null; this.tags = []; this.map = Object.create(null); this.name = this.input && this.input.name || 'filetag'; }
    TagsState.prototype._syncHidden = function () {
        if (!this.hidden) { this.hidden = el('input'); this.hidden.type = 'hidden'; this.hidden.name = this.name; this.c.parentNode.insertBefore(this.hidden, this.c.nextSibling); }
        this.hidden.value = toCSV(this.tags);
    };
    TagsState.prototype._setInputNameDisabled = function () {
        if (this.input) { this.input.removeAttribute('name'); this.input.setAttribute('aria-describedby', 'tagHelp'); this.input.setAttribute('aria-label', 'Adicionar categoria'); this.input.setAttribute('role', 'textbox'); this.input.setAttribute('aria-autocomplete', 'list'); }
    };
    TagsState.prototype._render = function () {
        var container = this.c; // remove existing chips except the text input
        var kids = [].slice.call(container.children); for (var i = 0; i < kids.length; i++) { if (kids[i] !== this.input) { container.removeChild(kids[i]); } }
        for (var j = 0; j < this.tags.length; j++) { var t = this.tags[j]; var chip = el('span', 'badge text-bg-primary d-inline-flex align-items-center'); chip.setAttribute('role', 'listitem'); chip.setAttribute('aria-label', 'Tag ' + t); chip.style.userSelect = 'none'; chip.style.paddingRight = '0.5rem'; chip.style.paddingLeft = '0.5rem'; chip.textContent = t; var close = el('button', 'btn-close btn-close-white ms-2'); close.type = 'button'; close.setAttribute('aria-label', 'Remove tag ' + t); (function (tag) { close.addEventListener('click', function () { this.remove(tag); }.bind(this)); }).call(this, t); chip.appendChild(close); container.insertBefore(chip, this.input); }
        this._syncHidden(); this._clearInvalid();
    };
    TagsState.prototype._clearInvalid = function () {
        if (this.invalid) { this.invalid.style.display = 'none'; }
        this.input.classList.remove('is-invalid'); this.c.classList.remove('is-invalid');
    };
    TagsState.prototype._showInvalid = function (msg) {
        if (this.invalid) { this.invalid.textContent = msg || 'Tags inválidas.'; this.invalid.style.display = 'block'; }
        this.input.classList.add('is-invalid'); this.c.classList.add('is-invalid');
    };
    TagsState.prototype._validateOne = function (tag) { if (!tag) return 'Tag vazia.'; if (tag.length > MAX_LEN) return 'Tag muito longa (max. ' + MAX_LEN + ').'; if (!TAG_RE.test(tag)) return 'Caracteres inválidos.'; return ''; };
    TagsState.prototype._validateAll = function () { if (this.tags.length > MAX_TAGS) return 'Muitas tags (max. ' + MAX_TAGS + ').'; var csv = toCSV(this.tags); if (csv.length > MAX_TOTAL) return 'Total muito grande (max. ' + MAX_TOTAL + ' chars).'; return ''; };
    TagsState.prototype.add = function (tag) { tag = (tag || '').trim(); if (!tag) return false; var err = this._validateOne(tag); if (err) { this._showInvalid(err); return false; } var key = tag.toLowerCase(); if (this.map[key]) { this._clearInvalid(); return false; } if (this.tags.length >= MAX_TAGS) { this._showInvalid('Muitas tags (max. ' + MAX_TAGS + ').'); return false; } this.tags.push(tag); this.map[key] = true; this._render(); return true; };
    TagsState.prototype.addMany = function (str) {
        var parts = str.split(','); var added = 0; for (var i = 0; i < parts.length; i++) { if (this.add(parts[i])) added++; }
        return added;
    };
    TagsState.prototype.remove = function (tag) {
        var key = tag.toLowerCase(); if (!this.map[key]) return; delete this.map[key]; for (var i = 0; i < this.tags.length; i++) { if (this.tags[i].toLowerCase() === key) { this.tags.splice(i, 1); break; } }
        this._render();
    };
    TagsState.prototype.last = function () { return this.tags.length ? this.tags[this.tags.length - 1] : ''; };
    TagsState.prototype.initFromCSV = function (csv) {
        var initial = normalizeCSV(csv); for (var i = 0; i < initial.length; i++) {
            var t = initial[i]; if (this.tags.length >= MAX_TAGS) break; var err = this._validateOne(t); if (!err) { var key = t.toLowerCase(); if (!this.map[key]) { this.tags.push(t); this.map[key] = true; } }
        }
        this._render();
    };
    TagsState.prototype.hookEvents = function () {
        var self = this; this.c.setAttribute('data-tags-init', '1'); this._setInputNameDisabled(); // Enter, comma, Tab => add
        this.input.addEventListener('keydown', function (e) {
            var v = self.input.value; if (e.key === 'Enter' || e.key === ',' || e.key === 'Tab') {
                e.preventDefault(); if (v) { self.addMany(v); self.input.value = ''; } else { self._clearInvalid(); }
            }
            else if (e.key === 'Backspace' && v === '') { // remove last
                var last = self.last(); if (last) { self.remove(last); e.preventDefault(); }
            }
        });
        this.input.addEventListener('paste', function (e) { var txt = (e.clipboardData || window.clipboardData).getData('text'); if (!txt) return; e.preventDefault(); self.addMany(txt); self.input.value = ''; });
        this.input.form && this.input.form.addEventListener('submit', function (e) { var err = self._validateAll(); if (err) { e.preventDefault(); self._showInvalid(err); self.input.focus(); } });
    };
    function init(container) { if (!container || container.getAttribute('data-tags-init') === '1') return null; var state = new TagsState(container); var csv = (state.input && state.input.value) || ''; state.initFromCSV(csv); state.hookEvents(); return state; }
    function addIfEmpty(container, tag) { if (!container) return; var st = container._tagsState || init(container); if (!st) return; if (st.tags.length === 0) { st.add(tag); } }
    function initAll() {
        var nodes = document.querySelectorAll('[id="tagField"].form-control[role="list"]'); for (var i = 0; i < nodes.length; i++) { var st = init(nodes[i]); if (st) { nodes[i]._tagsState = st; } }
    }
    window.TagsInput = { init: init, initAll: initAll, addIfEmpty: addIfEmpty };
})();
